mapper.select:
SELECT i.common_code_item_id
FROM tb_common_code_item i
WHERE i.tenant_id = #{tenantId}
  AND i.group_id = #{groupId}
  AND i.item_code = #{itemCode}
LIMIT 1

mapper.delete:
DELETE FROM tb_common_code_item
WHERE common_code_item_id = #{itemId}
  AND tenant_id = #{tenantId}
  AND group_id = #{groupId}

mapper.select:
SELECT COUNT(*)
FROM tb_common_code_item
WHERE parent_item_id = #{itemId}
  AND tenant_id = #{tenantId}
  AND group_id = #{groupId}
